(function(root){
  'use strict';
  const BASE='ruta-dian-2676-v1',R=root.RutaRewards;
  let b=null,scene=null,scenePromise=null,sceneAction='',sceneMonitor=null,syncTimer=null,syncBusy=false,syncAgain=false,lastSerialized='',authMode='login';
  const cloud={enabled:false,checked:false,user:null,revision:0,status:'local',conflict:null};
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const button=(text,action,value='',cls='')=>`<button class="btn ${cls}" data-action="extra-${action}" data-value="${esc(value)}">${text}</button>`;
  const uuid=()=>root.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);
  function normalize(raw){const priorities={};for(const l of b?.lessons()||[]){const v=raw?.priorities?.[l.id];if([0,1,2].includes(v))priorities[l.id]=v}return{pet:R.normalize(raw?.pet),priorities,priorityEnabled:raw?.priorityEnabled!==false}}
  function configure(bridge){b=bridge}
  function storageKey(){return cloud.user?BASE+':account:'+cloud.user.id:BASE}
  function persist(state){
    const serialized=JSON.stringify(state);if(serialized===lastSerialized)return;lastSerialized=serialized;
    const value=cloud.user?JSON.stringify({state,revision:cloud.revision,dirty:true,updatedAt:Date.now()}):serialized;
    let storageError=null;try{localStorage.setItem(storageKey(),value)}catch(error){storageError=error}
    if(cloud.user&&cloud.enabled&&!['loading','expired','conflict'].includes(cloud.status)){cloud.status='pending';clearTimeout(syncTimer);syncTimer=setTimeout(flush,800)}
    if(storageError&&!cloud.user)throw storageError;
  }
  async function api(path,body,method){
    const headers=body?{'Content-Type':'application/json','X-Ruta-Client':'web'}:{};
    const response=await fetch('/api/'+path,{method:method||(body?'POST':'GET'),credentials:'same-origin',headers,body:body?JSON.stringify(body):undefined,cache:'no-store'});
    let data;try{data=await response.json()}catch{throw Error('No se pudo conectar al servicio de cuentas.')}
    if(!response.ok){const error=new Error(data.error||'No se pudo guardar.');error.status=response.status;error.data=data;throw error}return data;
  }
  function mergeStudy(local,remote){
    const merged={...remote,...local,version:1,lessons:{...remote.lessons},stages:{...remote.stages},errors:{...remote.errors,...local.errors},daily:{...remote.daily},priorities:{...local.priorities}};
    for(const [id,l] of Object.entries(local.lessons||{})){const r=remote.lessons?.[id]||{};merged.lessons[id]={...r,...l,read:Boolean(r.read||l.read),best:Math.max(r.best||0,l.best||0),checks:[...new Set([...(r.checks||[]),...(l.checks||[])])],reviewAt:Math.max(r.reviewAt||0,l.reviewAt||0)}}
    for(const [id,l] of Object.entries(local.stages||{}))merged.stages[id]={best:Math.max(l.best||0,remote.stages?.[id]?.best||0)};
    const attempts=new Map();for(const a of [...(remote.attempts||[]),...(local.attempts||[])])attempts.set(a.id,a);merged.attempts=[...attempts.values()].sort((a,b)=>a.finished-b.finished).slice(-100);
    for(const [day,ids] of Object.entries(local.daily||{}))merged.daily[day]=[...new Set([...(remote.daily?.[day]||[]),...ids])];
    merged.pet=R.merge(local.pet,remote.pet);
    return merged;
  }
  async function loadAccount(user,{carryGuest=false}={}){
    const guest=b.state();cloud.user=user;cloud.status='loading';lastSerialized='';
    let cached=null;try{cached=JSON.parse(localStorage.getItem(storageKey())||'null')}catch{}
    try{
      const remote=await api('progress');cloud.revision=remote.revision;let chosen=remote.state;
      if(cached?.dirty&&cached.state)chosen=remote.state?mergeStudy(cached.state,remote.state):cached.state;
      if(!chosen)chosen=carryGuest?guest:b.initial();
      cloud.status='synced';b.replace(chosen);lastSerialized='';persist(b.state());await flush();
    }catch(error){cloud.status=error.status===401?'expired':'offline';if(cached?.state)b.replace(cached.state);else b.replace(carryGuest?guest:b.initial());b.toast('La cuenta está abierta. El servicio de guardado no responde; conservamos una copia en este dispositivo.');}
    b.render();
  }
  async function init(){
    try{const cfg=await api('config');cloud.enabled=cfg.accountsEnabled===true;cloud.checked=true;if(cloud.enabled){const {user}=await api('auth/me');if(user)await loadAccount(user)}}catch{cloud.checked=true;cloud.enabled=false}
    b.render();
  }
  async function flush(){
    clearTimeout(syncTimer);if(!cloud.user||!cloud.enabled||['loading','conflict','expired'].includes(cloud.status))return;
    if(syncBusy){syncAgain=true;return}syncBusy=true;cloud.status='saving';let snapshot=JSON.parse(JSON.stringify(b.state()));
    try{const result=await api('progress',{state:snapshot,revision:cloud.revision},'PUT');cloud.revision=result.revision;cloud.status='synced';const dirty=JSON.stringify(b.state())!==JSON.stringify(snapshot);try{localStorage.setItem(storageKey(),JSON.stringify({state:b.state(),revision:cloud.revision,dirty,updatedAt:Date.now()}))}catch{};if(dirty)syncAgain=true}
    catch(error){if(error.data?.code==='REVISION_CONFLICT'){cloud.conflict=error.data;cloud.status='conflict';b.toast('Hay cambios en otro dispositivo. Puedes unirlos desde Mi cuenta.')}else{cloud.status=error.status===401?'expired':'offline';b.toast(error.status===401?'La sesión venció. Tu copia local se conserva; vuelve a iniciar sesión.':'No pudimos sincronizar. Tu avance sigue guardado en este dispositivo.')}}
    finally{syncBusy=false;refreshStatus();if(syncAgain&&!['conflict','expired','offline'].includes(cloud.status)){syncAgain=false;await flush()}}
  }
  function statusLabel(){return !cloud.user?'Este navegador':({synced:'Guardado en tu cuenta',saving:'Guardando…',pending:'Pendiente de guardar',loading:'Cargando tu cuenta…',offline:'Copia local · sin conexión',expired:'Sesión vencida',conflict:'Cambios por unir'}[cloud.status]||'Tu cuenta')}
  function accountButton(){return `<button class="pill account-pill" data-action="navigate" data-value="cuenta" aria-label="${cloud.user?'Abrir mi cuenta':'Opciones de cuenta y guardado'}"><span class="sync-dot ${cloud.user&&cloud.status==='synced'?'online':''}"></span><span data-sync-label>${esc(cloud.user?statusLabel():cloud.enabled?'Entrar / crear cuenta':'Este navegador')}</span></button>`}
  function refreshStatus(){for(const el of document.querySelectorAll('[data-sync-label]'))el.textContent=statusLabel()}
  function outfitIcon(id){return '<svg width="48" height="48" viewBox="0 0 64 64" aria-hidden="true"><use href="wardrobe-icons.svg#'+esc(id)+'"></use></svg>'}
  function revealDog(){const el=document.querySelector('[data-dog-view]');if(!el)return;const rect=el.getBoundingClientRect();if(rect.top<40||rect.bottom>root.innerHeight)el.scrollIntoView({behavior:'smooth',block:'center'})}
  function petSnapshot(){const p=b.state().pet,s=R.stats(p);return{...p,...s,careStatus:R.care(p)}}
  function careMessage(c){return c.nutrition<40?'Una comida le vendría bien.':c.energy<30?'Es un buen momento para descansar.':c.mood<45?'Un ratito de juego le alegrará el día.':c.health>=70?'Está saludable y a gusto contigo.':'Con pequeños cuidados recuperará su bienestar.'}
  function healthHTML(compact=false){
    const c=R.care(b.state().pet);
    return `<div class="pet-health ${compact?'compact':''}"><div class="spread"><span>💚 ${compact?'Salud':'Salud y bienestar'}</span><strong>${c.health}<small>/100</small></strong></div><div class="care-track health" role="progressbar" aria-label="Salud del perrito" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${c.health}"><i style="width:${c.health}%"></i></div>${compact?'':`<div class="care-needs">${[['nutrition','🥣','Alimentación'],['mood','🎾','Ánimo'],['energy','🌙','Energía']].map(([id,emoji,label])=>`<div><div class="spread"><span>${emoji} ${label}</span><b>${c[id]}%</b></div><div class="care-track ${id}" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${c[id]}"><i style="width:${c[id]}%"></i></div></div>`).join('')}</div>`}<p class="care-message">${careMessage(c)}</p></div>`;
  }
  function tasksHTML(){
    const c=R.care(b.state().pet),date=new Date(c.day+'T12:00:00-05:00').toLocaleDateString('es-CO',{day:'numeric',month:'long'});
    return `<div class="spread"><span class="eyebrow">SU RUTINA DE HOY</span><span class="badge ${c.tasks===2?'done':''}">${c.tasks}/2</span></div><h3 style="margin-top:10px">Aprende y cuídalo</h3><p class="care-date">${date} · hora de Colombia</p><div class="care-task ${c.study?'done':''}"><span aria-hidden="true">${c.study?'✓':'1'}</span><div><strong>Lee o repasa un tema</strong><p>Completa una lectura o valora una tarjeta de repaso.</p>${c.study?'<small>Comida y juego obtenidos</small>':button('Ir a estudiar →','care-study','','small')}</div></div><div class="care-task ${c.practice?'done':''}"><span aria-hidden="true">${c.practice?'✓':'2'}</span><div><strong>Completa una práctica</strong><p>Responde todas las preguntas. Cualquier nota cuenta para esta tarea.</p>${c.practice?'<small>Comida y juego obtenidos</small>':button('Ir a practicar →','care-practice','','small')}</div></div><div class="care-prize">Cada tarea da <b>1 comida + 1 juego de hoy</b>.<br>🎾 <b>${c.games}</b> ${c.games===1?'juego disponible':'juegos disponibles'}</div><p class="care-footnote">Las tareas y los juegos se renuevan a las 00:00 en Colombia. La comida que guardas no vence.</p>${c.tasks===2?'<p class="care-success">¡Rutina completada! Ya puedes darle sus cuidados.</p>':''}`;
  }
  function syncCareUI(){
    if(!b)return;
    for(const el of document.querySelectorAll('[data-pet-health]')){const html=healthHTML(el.dataset.petHealth==='compact');if(el.innerHTML!==html)el.innerHTML=html}
    for(const el of document.querySelectorAll('[data-care-tasks]')){const html=tasksHTML();if(el.innerHTML!==html)el.innerHTML=html}
    const c=R.care(b.state().pet),play=document.querySelector('[data-action="extra-pet-animate"][data-value="play"]');if(play){const label=play.querySelector('[data-play-label]');if(label)label.textContent='Jugar ('+c.games+')';play.title=c.games?'Usa un juego de hoy: +25 ánimo, −10 energía':'Completa una tarea diaria para ganar un juego'}
    for(const el of document.querySelectorAll('[data-care-summary]'))el.textContent=c.tasks+'/2 tareas de hoy \u00b7 '+c.games+' juegos disponibles';
    const rest=document.querySelector('[data-rest-note]');if(rest)rest.textContent=c.rested?'Descanso de hoy recibido. Puedes seguir viendo su animación.':'Descansar recupera 30 de energía una vez al día.';
  }
  function noteStudy(kind){const result=R.task(b.state().pet,kind);b.state().pet=result.pet;return result}
  function dogBox(compact=false){return `<div class="dog-view ${compact?'compact':''}" data-dog-view data-compact="${compact}" aria-label="${esc(b.state().pet.name)}, tu compañero de estudio"></div>`}
  const actionLabels={idle:'Está a gusto contigo.',feed:'Disfrutando su merienda.',pet:'Disfrutando las caricias.',play:'Jugando con su pelota.',sleep:'Descansando en su cama.',stretch:'Estirando sus patitas.',sit:'Sentado y atento.',celebrate:'Celebrando un logro contigo.'};
  const phaseLabels={anticipate:'¡Ya vio la comida!',sniff:'Olfateando sus croquetas.',eat:'Masticando con gusto.',lick:'Relamiéndose después de comer.',satisfied:'Una merienda que lo dejó feliz.'};
  let nextCareRefresh=0;
  function showAnimationStatus(){
    if(Date.now()>=nextCareRefresh){syncCareUI();nextCareRefresh=Date.now()+60000}
    const status=scene?.getAnimationState?.()||{action:'idle',phase:'idle',busy:false};
    const el=document.querySelector('[data-pet-status]');if(el){const text=b.state().pet.name+' · '+(status.action==='feed'?phaseLabels[status.phase]||actionLabels.feed:actionLabels[status.action]||actionLabels.idle);if(el.textContent!==text)el.textContent=text;el.dataset.action=status.action;el.dataset.phase=status.phase||''}
    const feeding=status.action==='feed'&&status.busy;
    for(const control of document.querySelectorAll('[data-action="extra-feed"],[data-action="extra-feed-preview"]'))control.disabled=feeding;
    for(const control of document.querySelectorAll('[data-action="extra-pet-animate"]'))control.setAttribute('aria-pressed',String(control.dataset.value===status.action));
    return status;
  }
  function syncPetCounters(){const pet=petSnapshot();for(const key of ['food','fed','stars']){const el=document.querySelector('[data-pet-count="'+key+'"]');if(el)el.textContent=pet[key]}const control=document.querySelector('[data-action="extra-feed"]');if(control)control.textContent='Dar una comida'+(pet.food?' ('+pet.food+')':'')}
  function runSceneAction(action){
    if(!scene){sceneAction=action;return false}
    if(action==='feed')scene.feed();else if(action==='celebrate')scene.celebrate();else scene.play?.(action);
    revealDog();showAnimationStatus();return true;
  }
  function attachScene(){
    disposeScene();const el=document.querySelector('[data-dog-view]');if(!el)return;
    scenePromise??=import('./dog-scene.js');scenePromise.then(({mountDog})=>{if(!el.isConnected)return;scene=mountDog(el,petSnapshot(),{compact:el.dataset.compact==='true'});if(sceneAction){const action=sceneAction;sceneAction='';runSceneAction(action)}showAnimationStatus();if(document.querySelector('[data-pet-status]'))sceneMonitor=setInterval(showAnimationStatus,240)}).catch(()=>{if(el.isConnected)el.innerHTML='<img src="dog-fallback.svg" alt="Perrito de estudio" style="width:100%;height:100%;object-fit:contain">'})
  }
  function disposeScene(){if(sceneMonitor!==null){clearInterval(sceneMonitor);sceneMonitor=null}if(scene){scene.dispose();scene=null}}
  function petCard(){const p=petSnapshot();return `<div class="aside-card pet-summary"><div class="spread"><div><span class="eyebrow">TU COMPAÑERO</span><h3 style="margin-top:5px">${esc(p.name)} va contigo</h3></div><span class="pet-paw">🐾</span></div><div data-pet-health="compact">${healthHTML(true)}</div><div class="pet-stats"><span>⭐ ${p.stars} ${p.stars===1?'estrella':'estrellas'}</span><span>🥣 ${p.food} ${p.food===1?'comida':'comidas'}</span></div><p class="muted" data-care-summary style="font-size:11px;margin-top:10px">${p.careStatus.tasks}/2 tareas de hoy · ${p.careStatus.games} juegos disponibles</p>${button('Cuidar a mi perrito','pet-open','','small')}</div>`}
  function rewardPanel(a){if(!a?.reward||(!a.reward.food&&!a.reward.stars))return '';const p=petSnapshot(),reward=a.reward;return `<section class="reward-panel"><div>${dogBox(true)}</div><div><span class="eyebrow">UN LOGRO, UN REGALO</span><h3>¡${esc(p.name)} tiene algo que celebrar!</h3><p>${reward.stars?`⭐ +${reward.stars} ${reward.stars===1?'estrella':'estrellas'} · `:''}🥣 +${reward.food} ${reward.food===1?'comida':'comidas'}</p>${reward.dailyTask?'<p class="reward-unlock">Tarea diaria completada: el premio incluye 1 comida extra y tienes 1 juego nuevo para hoy.</p>':''}${reward.unlocks?.length?`<p class="reward-unlock">Desbloqueaste: ${reward.unlocks.map(id=>esc(R.outfits.find(o=>o.id===id)?.name||id)).join(', ')}.</p>`:''}${button('Abrir sus regalos','pet-open','','small')}</div></section>`}
  function petPage(){const p=petSnapshot(),next=R.outfits.find(o=>o.stars>p.stars);return `<div class="page-heading"><h1>Tu compañero de camino</h1><p>Aprender también puede dejar pequeñas alegrías.</p></div><div class="pet-layout"><section class="panel pet-room"><div class="spread"><div><span class="eyebrow">${p.stars>=15?'EXPLORADOR EXPERTO':p.stars>=4?'ESTUDIANTE CURIOSO':'PRIMEROS PASOS'}</span><h2 style="margin-top:6px">${esc(p.name)}</h2></div>${button('Cambiar nombre','pet-name','','small subtle')}</div><div data-pet-health="full">${healthHTML()}</div>${dogBox()}<p class="dog-hint">Arrastra para girarlo. También puedes usar las flechas del teclado.</p><div class="pet-stats large"><span>⭐ <b data-pet-count="stars">${p.stars}</b> ${p.stars===1?'estrella':'estrellas'}</span><span>🥣 <b data-pet-count="food">${p.food}</b> ${p.food===1?'comida':'comidas'}</span><span>💚 <b data-pet-count="fed">${p.fed}</b> ${p.fed===1?'merienda':'meriendas'}</span></div><div class="line wrap" style="justify-content:center;margin-top:20px">${button(`Dar una comida${p.food?' ('+p.food+')':''}`,'feed','','primary')}${button('Ver cómo come','feed-preview','','')}</div><div class="pet-action-status" role="status" aria-live="polite" data-pet-status>${esc(p.name)} · Está a gusto contigo.</div><div class="pet-interactions" role="group" aria-label="Interactuar con el perrito">${[['pet','🤍','Acariciar'],['play','🎾','Jugar'],['stretch','🐾','Estirarse'],['sleep','🌙','Descansar'],['sit','☀️','Sentarse'],['celebrate','✨','Celebrar']].map(([id,emoji,label])=>`<button class="pet-interaction" data-action="extra-pet-animate" data-value="${id}" aria-pressed="false"><span aria-hidden="true">${emoji}</span><span ${id==='play'?'data-play-label':''}>${label}${id==='play'?' ('+p.careStatus.games+')':''}</span></button>`).join('')}</div><p class="care-rest-note" data-rest-note>${p.careStatus.rested?'Descanso de hoy recibido. Puedes seguir viendo su animación.':'Descansar recupera 30 de energía una vez al día.'}</p><p class="pet-preview-note">“Ver cómo come” es una vista previa: no gasta comida ni aumenta su salud.</p><p class="muted" style="font-size:11px;margin:14px auto 0;max-width:420px">La alimentación baja 12 puntos por día; el ánimo, 10; la energía, 8, incluso al cerrar la app. Ningún indicador baja de 20. Tu compañero siempre puede recuperarse; tus estrellas y prendas se conservan.</p></section><aside class="stack"><section class="panel care-daily" data-care-tasks>${tasksHTML()}</section><section class="panel"><h3>El próximo regalo</h3>${next?`<div class="next-gift"><span>${outfitIcon(next.id)}</span><div><strong>${next.name}</strong><p class="muted">${next.stars-p.stars} ${next.stars-p.stars===1?'estrella':'estrellas'} para desbloquear</p></div></div><div class="stage-progress"><i style="width:${Math.min(100,Math.round(p.stars/next.stars*100))}%"></i></div>`:'<p class="muted" style="font-size:13px;margin-top:12px">Tu colección de ropa está completa. Sigue sumando aprendizajes y comida.</p>'}</section><section class="panel longtext"><h3>Cómo llegan los premios</h3><p><b>Tareas diarias:</b> una comida y un juego por leer o repasar, y otra comida y otro juego por responder una práctica completa. Cada tarea premia una vez al día.</p><p><b>80% o más:</b> una comida por examen y una estrella por la primera meta de cada tema o etapa.</p><p><b>100%:</b> dos comidas y una estrella extra la primera vez que logras un resultado perfecto en esa meta.</p><p><b>Autoinforme completo:</b> una comida por completar el formato. Tus respuestas personales no se califican.</p><p>Los premios por resultados se suman a la rutina diaria. Comer recupera hasta 30 de alimentación, 8 de ánimo y 5 de energía. Jugar recupera hasta 25 de ánimo y usa 10 de energía; necesita al menos 30. Las caricias y otras animaciones siempre están disponibles.</p></section></aside></div><section style="margin-top:26px"><div class="section-head"><h2>Su pequeño guardarropa</h2><p>Elige una prenda desbloqueada para verla en el perrito.</p></div><div class="wardrobe-grid">${R.outfits.map(o=>{const unlocked=p.stars>=o.stars,equipped=p.outfit===o.id;return `<article class="wardrobe-card ${equipped?'equipped':''} ${unlocked?'':'locked'}"><div class="outfit-icon">${outfitIcon(o.id)}</div><h3>${o.name}</h3><p>${o.description}</p><span class="badge ${unlocked?'done':''}">${unlocked?equipped?'Puesta':'Disponible':o.stars+' estrellas'}</span><button class="btn small ${equipped?'primary':''}" data-action="extra-outfit" data-value="${o.id}" ${unlocked?'':'disabled'}>${equipped?'La está usando':unlocked?'Poner esta prenda':'Por desbloquear'}</button></article>`}).join('')}</div></section>`}
  function prioritiesPage(){const s=b.state(),groups=b.stages();return `<div class="page-heading"><h1>Tu estudio, en tu orden</h1><p>Elige en qué ejes quieres concentrarte primero. Todo el temario sigue disponible.</p></div><section class="panel priority-intro"><div class="spread wrap"><div><h3>Usar mis prioridades</h3><p>La próxima lección y el orden de las etapas siguen tus elecciones. El diagnóstico y los casos funcionales del simulacro dan más oportunidades a tus ejes de prioridad alta.</p></div><label class="priority-switch"><input type="checkbox" id="priority-enabled" ${s.priorityEnabled?'checked':''}>Activadas</label></div><div class="line wrap" style="margin-top:18px"><span class="tag priority-high">Alta · empieza aquí</span><span class="tag">Normal · mantén el ritmo</span><span class="tag">Baja · repasa después</span>${button('Restablecer orden','priority-reset','','small subtle')}</div></section><div class="priorities-groups">${groups.map(g=>`<section class="panel"><div class="spread"><h3>${g.n}. ${g.title}</h3>${button('Priorizar etapa','priority-stage',g.id,'small subtle')}</div><div class="priority-rows">${b.lessons().filter(l=>l.stage===g.id).map(l=>`<label class="priority-row"><div><strong>${esc(l.title)}</strong><span>${esc(l.indicator)}</span></div><select data-priority="${l.id}" aria-label="Prioridad de ${esc(l.indicator)}"><option value="2" ${(s.priorities[l.id]??1)===2?'selected':''}>Alta</option><option value="1" ${(s.priorities[l.id]??1)===1?'selected':''}>Normal</option><option value="0" ${(s.priorities[l.id]??1)===0?'selected':''}>Baja</option></select></label>`).join('')}</div></section>`).join('')}</div>`}
  function orderedLessons(list){return b.state().priorityEnabled?list.slice().sort((a,c)=>(b.state().priorities[c.id]??1)-(b.state().priorities[a.id]??1)):list.slice()}
  function orderedStages(list){return b.state().priorityEnabled?list.slice().sort((a,c)=>Math.max(...b.lessons().filter(l=>l.stage===c.id).map(l=>b.state().priorities[l.id]??1))-Math.max(...b.lessons().filter(l=>l.stage===a.id).map(l=>b.state().priorities[l.id]??1))):list.slice()}
  function weighted(items,count){const pool=items.slice(),chosen=[];while(pool.length&&chosen.length<count){let weights=pool.map(q=>b.state().priorityEnabled?(b.state().priorities[q.lessonId]??1)+1:1),target=Math.random()*weights.reduce((a,n)=>a+n,0),index=0;for(;index<weights.length-1;index++){target-=weights[index];if(target<=0)break}chosen.push(pool.splice(index,1)[0])}return chosen}
  function accountPage(){
    if(!cloud.enabled)return `<div class="page-heading"><h1>Tu avance, contigo</h1><p>En este despliegue puedes estudiar sin crear una cuenta.</p></div><section class="panel longtext"><span class="pill green">Modo de navegador</span><h2 style="margin-top:18px">Todo sigue a tu ritmo</h2><p>Lecciones, exámenes, prioridades y premios del perrito se conservan en este navegador. Descarga un respaldo si quieres llevarlos a otro dispositivo.</p><p>Las cuentas aparecerán automáticamente cuando el servicio de guardado esté configurado.</p><button class="btn primary" style="margin-top:20px" data-action="navigate" data-value="progreso">Mis respaldos y progreso →</button></section>`;
    if(cloud.user)return `<div class="page-heading"><h1>Un camino que puedes retomar</h1><p>Tu cuenta conserva el estudio y los regalos de tu compañero.</p></div><section class="panel longtext"><span class="pill green" data-sync-label>${statusLabel()}</span><h2 style="margin-top:20px">Hola, ${esc(cloud.user.name)}</h2><p>${esc(cloud.user.email)}</p><p>El avance, las prioridades y la mascota se sincronizan con tu cuenta. También mantenemos una copia en este dispositivo para los momentos sin conexión.</p>${cloud.status==='conflict'?'<div class="scope-note">Otro dispositivo guardó cambios. Puedes unir las lecturas, mejores resultados, intentos y premios sin duplicar regalos.</div>'+button('Unir cambios y guardar','merge-conflict','','primary'):''}<div class="line wrap" style="margin-top:22px">${button('Guardar ahora','sync','','primary')}${button('Unir avance de este navegador','merge-guest','','')}${button('Cerrar sesión','logout','','subtle')}</div><p style="font-size:11px">El botón de unión conserva los mejores resultados y reúne los premios. Las prioridades actuales de la cuenta se mantienen.</p></section>`;
    return `<div class="page-heading"><h1>Lleva tu ruta a otro dispositivo</h1><p>Crea una cuenta o entra para continuar donde lo dejaste.</p></div><section class="panel auth-panel"><div class="filter-row"><button data-action="extra-auth-mode" data-value="login" class="${authMode==='login'?'active':''}">Iniciar sesión</button><button data-action="extra-auth-mode" data-value="register" class="${authMode==='register'?'active':''}">Crear cuenta</button></div><form id="auth-form" data-auth-mode="${authMode}" class="stack">${authMode==='register'?'<label class="field">Tu nombre<input name="name" autocomplete="name" minlength="2" maxlength="60" required></label>':''}<label class="field">Correo electrónico<input name="email" type="email" autocomplete="email" maxlength="254" required></label><label class="field">Contraseña<input name="password" type="password" autocomplete="${authMode==='register'?'new-password':'current-password'}" minlength="10" maxlength="128" required><small>De 10 a 128 caracteres.</small></label><p id="auth-error" class="danger" role="alert"></p><button class="btn primary" type="submit">${authMode==='register'?'Crear cuenta y guardar mi avance':'Entrar a mi cuenta'}</button></form><p class="muted" style="font-size:11px;margin-top:20px">${authMode==='register'?'Al crear tu cuenta, guardaremos también el avance y los premios que ya tienes en este navegador.':'Al entrar verás el avance de tu cuenta. El avance de invitado se conserva por separado.'}</p><button class="text-btn" style="margin-top:15px" data-action="navigate" data-value="ruta">Continuar sin iniciar sesión →</button><p class="muted" style="font-size:10px;margin-top:17px">Este acceso sencillo usa correo y contraseña. La recuperación de contraseña por correo no está habilitada.</p></section>`;
  }
  async function action(name,value){
    if(name==='pet-open')b.go('mascota');
    if(name==='care-study'){const list=orderedLessons(b.lessons()),next=list.find(l=>!b.state().lessons[l.id]?.read)||list[0];if(next)b.go('lesson/'+next.id)}
    if(name==='care-practice')b.go('simulacros');
    if(name==='pet-animate'||name==='pet-play'){
      if(name==='pet-play')value='play';
      const status=showAnimationStatus();if(status.busy){b.toast('Espera a que termine su actividad.');return}
      if(value==='play'||value==='sleep'){
        const next=R.interact(b.state().pet,value==='play'?'play':'rest');
        if(!next.ok&&value==='play'){b.toast(next.reason==='energy'?'Primero déjalo descansar para recuperar energía.':'Completa una tarea de hoy para ganar comida y un juego.');return}
        if(next.ok){b.state().pet=next.pet;b.save();syncCareUI();b.toast(value==='play'?'¡A jugar! +25 de ánimo · −10 de energía.':'Una pausa reparadora: +30 de energía.')}
      }
      runSceneAction(value);
    }
    if(name==='feed-preview'){if(showAnimationStatus().action==='feed'&&showAnimationStatus().busy)return;runSceneAction('feed');b.toast('Vista previa: tus comidas se conservan.')}
    if(name==='feed'){
      const status=showAnimationStatus();if(status.action==='feed'&&status.busy)return;
      const next=R.feed(b.state().pet,'feed:'+uuid());if(!next.ok){b.toast('Completa una tarea diaria para ganar comida, sin exigir una nota mínima.');return}
      b.state().pet=next.pet;b.save();
      if(scene){scene.update(petSnapshot());revealDog();syncPetCounters();syncCareUI();showAnimationStatus()}else{sceneAction='feed';b.render()}
      b.toast('¡Una merienda para '+next.pet.name+'! +30 alimentación · +8 ánimo · +5 energía.');
    }
    if(name==='pet-name'){b.dialog('Un nombre para tu compañero',`<div class="field"><label for="pet-name">Nombre del perrito</label><input id="pet-name" maxlength="20" value="${esc(b.state().pet.name)}"></div>`,button('Guardar nombre','save-pet-name','','primary')+button('Cancelar','close'));}
    if(name==='save-pet-name'){b.state().pet.name=document.getElementById('pet-name').value.trim().slice(0,20)||'Toby';b.save();b.close();b.render()}
    if(name==='close')b.close();if(name==='outfit'){const outfit=R.outfits.find(o=>o.id===value);if(outfit&&outfit.stars<=R.stats(b.state().pet).stars){b.state().pet.outfit=value;b.save();b.render();b.toast('Una nueva pinta para '+b.state().pet.name+'.')}}
    if(name==='priority-reset'){b.state().priorities={};b.state().priorityEnabled=true;b.save();b.render();b.toast('Orden de estudio restablecido.')}
    if(name==='priority-stage'){for(const l of b.lessons().filter(l=>l.stage===value))b.state().priorities[l.id]=2;b.state().priorityEnabled=true;b.save();b.render();b.toast('Etapa marcada con prioridad alta.')}
    if(name==='auth-mode'){authMode=value==='register'?'register':'login';b.render()}
    if(name==='sync'){await flush();if(cloud.status==='synced')b.toast('Tu avance quedó guardado en la cuenta.');b.render()}
    if(name==='merge-conflict'&&cloud.conflict){let remote=cloud.conflict;cloud.revision=remote.revision;cloud.conflict=null;cloud.status='synced';b.replace(mergeStudy(b.state(),remote.state||b.initial()));lastSerialized='';b.save();await flush();b.render()}
    if(name==='merge-guest'){let guest=null;try{guest=JSON.parse(localStorage.getItem(BASE)||'null')}catch{}if(guest){b.replace(mergeStudy(b.state(),guest));lastSerialized='';b.save();await flush();b.render();b.toast('Lecturas, resultados y premios reunidos.')}else b.toast('No hay avance de invitado para unir.')}
    if(name==='logout'){try{await flush();await api('auth/logout',{});cloud.user=null;cloud.revision=0;cloud.status='local';lastSerialized='';let guest=null;try{guest=JSON.parse(localStorage.getItem(BASE)||'null')}catch{}b.replace(guest||b.initial());b.save();b.render();b.toast('Sesión cerrada. Estás en el modo de este navegador.')}catch(error){b.toast(error.message)}}
  }
  document.addEventListener('submit',async event=>{
    const form=event.target;if(form.id!=='auth-form')return;event.preventDefault();if(!form.reportValidity())return;const submit=form.querySelector('button[type="submit"]'),errorEl=form.querySelector('#auth-error');submit.disabled=true;errorEl.textContent='';
    try{const fields=new FormData(form);const result=await api('auth/'+form.dataset.authMode,{email:fields.get('email'),password:fields.get('password'),name:fields.get('name')||''});form.reset();await loadAccount(result.user,{carryGuest:form.dataset.authMode==='register'});b.go('cuenta');b.toast('Tu cuenta está lista.')}catch(error){errorEl.textContent=error.message}finally{submit.disabled=false}
  });
  document.addEventListener('change',event=>{if(!b)return;if(event.target.dataset.priority){b.state().priorities[event.target.dataset.priority]=Number(event.target.value);b.save();b.toast('Prioridad guardada.')}if(event.target.id==='priority-enabled'){b.state().priorityEnabled=event.target.checked;b.save();b.toast(event.target.checked?'Usaremos tus prioridades.':'Seguiremos el orden de las etapas.')}});
  root.addEventListener('online',()=>{if(cloud.user){cloud.status='pending';flush()}});
  root.addEventListener('focus',syncCareUI);
  setInterval(()=>{if(b&&!document.hidden)syncCareUI()},60000);
  root.RutaExtras={configure,normalize,persist,init,accountButton,statusLabel,petSnapshot,dogBox,attachScene,disposeScene,petCard,rewardPanel,petPage,prioritiesPage,accountPage,orderedLessons,orderedStages,weighted,action,mergeStudy,noteStudy,cloud,setSceneAction:action=>sceneAction=action};
})(window);
